gVf(){return"\u064a\u0637\u0627\u0628\u0642 \u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0641\u064a \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0628\u0627\u0644\u0641\u0639\u0644 \u0645\u0627 \u0647\u0648 \u0645\u0648\u062c\u0648\u062f \u0641\u0639\u0644\u064a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0631\u0641."},
Vg(a,b){return"\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0645\u062a\u0648\u0641\u0631 "+a+" "+b+" \u0645\u0645\u0627 \u064a\u0638\u0647\u0631\u0647 \u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0641\u064a \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062d\u0627\u0644\u064a\u064b\u0627 \u2014 \u0645\u062a\u0648\u0642\u0639 \u0623\u062b\u0646\u0627\u0621 \u0628\u064a\u0639 \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u0645\u064f\u0634\u062a\u0631\u0649 \u0642\u0628\u0644 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u062e\u0632\u0648\u0646 \u0627\u0644\u062f\u0627\u0626\u0645. \u064a\u064f\u0631\u062d\u0651\u0644 \u0642\u064a\u062f \u062a\u0635\u062d\u064a\u062d \u0644\u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u0642\u0627\u0628\u0644 \u062d\u0642\u0648\u0642 \u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a\u060c \u0648\u0644\u064a\u0633 \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062a\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0631\u0628\u062d \u0623\u064a \u0641\u062a\u0631\u0629 \u0633\u0627\u0628\u0642\u0629."},
