W5(a){var s=null
return A.aH(a,s,this.a,s,"\u0634\u064a\u0643 \u0648\u0627\u062d\u062f \u062a\u0645\u062a \u062a\u0633\u0648\u064a\u062a\u0647",""+a+" \u0634\u064a\u0643\u0627\u062a \u062a\u0645\u062a \u062a\u0633\u0648\u064a\u062a\u0647\u0627",s,s)+" \u2014 \u0645\u0639\u0638\u0645\u0647\u0627 \u0645\u0633\u062a\u0648\u0631\u062f\u0629 \u0645\u0646 Manager.io \u2014 \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062a\u064a \u062a\u0645\u062b\u0644\u0647\u0627. \u062d\u0630\u0641 \u0623\u062d\u062f\u0647\u0627 \u0627\u0644\u0622\u0646 \u0633\u064a\u0632\u064a\u0644 \u0641\u0642\u0637 \u0627\u0644\u0634\u064a\u0643 \u0627\u0644\u0645\u0631\u0626\u064a\u060c \u062a\u0627\u0631\u0643\u064b\u0627 \u0623\u0645\u0648\u0627\u0644\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 (\u0627\u0644\u0630\u0645\u0645 \u0627\u0644\u062f\u0627\u0626\u0646\u0629\u060c \u0627\u0644\u0630\u0645\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0627\u0644\u0646\u0642\u062f\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u0643) \u062f\u0648\u0646 \u0645\u0633\u0627\u0633 \u062a\u0645\u0627\u0645\u064b\u0627. \u064a\u0631\u0628\u0637 \u0643\u0644 \u0648\u0627\u062d\u062f \u0628\u0642\u064a\u0648\u062f\u0647 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u062d\u062a\u0649 \u064a\u0639\u0645\u0644 \u0627\u0644\u062d\u0630\u0641 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u0645\u0646 \u0627\u0644\u0622\u0646 \u0641\u0635\u0627\u0639\u062f\u064b\u0627 \u2014 \u0644\u0627 \u064a\u062d\u0631\u0643 \u0623\u064a \u0623\u0645\u0648\u0627\u0644 \u0628\u062d\u062f \u0630\u0627\u062a\u0647."},
gVl(){return"\u0631\u0628\u0637"},
gVp(){return"\u0641\u0648\u0627\u062a\u064a\u0631 \u0628\u062f\u0648\u0646 \u062a\u0627\u0631\u064a\u062e \u0627\u0633\u062a\u062d\u0642\u0627\u0642"},
gVn(){return"\u0643\u0644 \u0641\u0627\u062a\u0648\u0631\u0629 \u0644\u062f\u064a\u0647\u0627 \u062a\u0627\u0631\u064a\u062e \u0627\u0633\u062a\u062d\u0642\u0627\u0642\u060c \u0644\u0630\u0627 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0623\u062e\u0631\u0629/\u0627\u0644\u0645\u0633\u062a\u062d\u0642\u0629 \u0642\u0631\u064a\u0628\u064b\u0627 \u0641\u064a \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u062f\u0642\u064a\u0642\u0629."},
Vo(a){var s=null
return A.aH(a,s,this.a,s,"\u0641\u0627\u062a\u0648\u0631\u0629 \u0648\u0627\u062d\u062f\u0629",""+a+" \u0641\u0648\u0627\u062a\u064a\u0631",s,s)+" \u2014 \u0645\u0639\u0638\u0645\u0647\u0627 \u0645\u0633\u062a\u0648\u0631\u062f\u0629 \u0645\u0646 Manager.io \u2014 \u0644\u064a\u0633 \u0644\u0647\u0627 \u062a\u0627\u0631\u064a\u062e \u0627\u0633\u062a\u062d\u0642\u0627\u0642 \u0645\u062d\u062f\u062f\u060c \u0644\u0630\u0627 \u0644\u0627 \u062a\u0638\u0647\u0631 \u0623\u0628\u062f\u064b\u0627 \u0643\u0645\u062a\u0623\u062e\u0631\u0629 \u0623\u0648 \u0645\u0633\u062a\u062d\u0642\u0629 \u0642\u0631\u064a\u0628\u064b\u0627 \u0641\u064a \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u064a\u0627\u062f\u0629. \u064a\u062d\u062f\u062f \u0643\u0644 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0634\u0631\u0648\u0637 \u0627\u0626\u062a\u0645\u0627\u0646 \u0639\u0645\u064a\u0644\u0647\u0627 (\u0646\u0642\u062f\u064b\u0627\u060c \u0641\u0627\u062a\u0648\u0631\u0629 \u0628\u0641\u0627\u062a\u0648\u0631\u0629\u060c \u0623\u064a\u0627\u0645\u060c \u0623\u0648 \u0645\u0641\u062a\u0648\u062d) \u2014 \u0644\u0627 \u064a\u063a\u064a\u0631 \u0623\u064a \u0645\u0628\u0644\u063a \u0645\u0633\u062a\u062d\u0642."},
gVW(){return"\u062a\u0639\u064a\u064a\u0646 \u062a\u0648\u0627\u0631\u064a\u062e \u0627\u0644\u0627\u0633\u062a\u062d\u0642\u0627\u0642"},
gVA(){return"\u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u0631\u0648\u0627\u062a\u0628 \u0645\u062a\u0628\u0642\u064a\u0629"},
gVy(){return"\u0644\u0645 \u062a\u062a\u0631\u0643 \u0623\u064a \u0639\u0645\u0644\u064a\u0629 \u0631\u0648\u0627\u062a\u0628 \u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u064a\u062a\u064a\u0645\u0629 \u062e\u0644\u0641\u0647\u0627."},
Vz(a,b){var s=null
return A.aH(a,s,this.a,s,"\u0642\u064a\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u0648\u0627\u062d\u062f",""+a+" \u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630",s,s)+" ("+b+") \u0645\u0646 \u0639\u0645\u0644\u064a\u0629 \u0631\u0648\u0627\u062a\u0628 \u062d\u064f\u0630\u0641\u062a \u0642\u0628\u0644 \u0623\u0646 \u062a\u062a\u0645\u0643\u0646 \u0645\u0646 \u0639\u0643\u0633 \u062a\u0631\u062d\u064a\u0644\u0627\u062a\u0647\u0627 \u0627\u0644\u062e\u0627\u0635\u0629 \u2014 \u0644\u0627 \u062a\u0632\u0627\u0644 \u062a\u0638\u0647\u0631 \u0641\u064a \u0627\u0644\u0646\u0642\u062f\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u0643 \u062f\u0648\u0646 \u0637\u0631\u064a\u0642\u0629 \u0644\u062a\u0639\u062f\u064a\u0644\u0647\u0627 \u0623\u0648 \u0625\u0632\u0627\u0644\u062a\u0647\u0627 \u0645\u0646 \u0647\u0646\u0627\u0643. \u064a\u0632\u064a\u0644 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0648\u062f \u0628\u0627\u0644\u0636\u0628\u0637\u061b \u0631\u0635\u064a\u062f \u0631\u0627\u062a\u0628 \u0627\u0644\u0645\u0648\u0638\u0641 \u0646\u0641\u0633\u0647 \u0644\u0627 \u064a\u062a\u0623\u062b\u0631."},
