gVP(){return"\u0627\u0645\u0633\u062d \u0645\u062e\u0632\u0648\u0646 \u0643\u0644 \u0635\u0646\u0641 \u0648\u062a\u0627\u0631\u064a\u062e \u062d\u0631\u0643\u062a\u0647 \u0648\u0637\u0628\u0642\u0627\u062a \u062a\u0643\u0644\u0641\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0635\u0641\u0631."},
gVU(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062a"},
gVT(){return"\u0643\u0644 \u0641\u0627\u062a\u0648\u0631\u0629 \u0648\u0634\u0631\u0627\u0621 \u0648\u0625\u0634\u0639\u0627\u0631 \u0648\u0634\u064a\u0643 \u0648\u062a\u0633\u0644\u064a\u0645 \u0648\u0633\u0646\u062f \u0648\u0642\u064a\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u0648\u062d\u0631\u0643\u0629 \u0645\u062e\u0632\u0648\u0646 \u0648\u0639\u0645\u0644\u064a\u0629 \u0631\u0648\u0627\u062a\u0628 \u0648\u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0642\u064a\u0642 \u2014 \u064a\u064f\u0645\u062d\u0649 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629. \u064a\u0628\u0642\u0649 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0634\u0631\u0643\u0629 (\u0627\u0644\u0639\u0645\u0644\u0627\u0621\u060c \u0627\u0644\u0645\u0648\u0631\u062f\u0648\u0646\u060c \u0627\u0644\u0623\u0635\u0646\u0627\u0641\u060c \u0627\u0644\u0645\u0648\u0638\u0641\u0648\u0646\u060c \u062f\u0644\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a) \u0643\u0645\u0627 \u0647\u0648 \u062a\u0645\u0627\u0645\u064b\u0627."},
gQT(){return"\u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u0627\u0644\u0643 \u0641\u0642\u0637 \u0646\u0633\u062e \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u062d\u062a\u064a\u0627\u0637\u064a\u064b\u0627 \u0623\u0648 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627."},
