gNG(){return"\u0648\u06c1 \u0633\u0627\u0626\u0646 \u0627\u0646 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06cc\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba \u06af\u06d2 \u2014 \u0627\u0633 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0627\u0646\u06c1\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0628\u0646\u0627\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4"},
gNB(){return"\u06a9\u0631\u062f\u0627\u0631"},
gNF(){return"\u0633\u06cc\u0644\u0632 \u0679\u06cc\u0645"},
gQW(){return"\u0627\u06a9\u0627\u0624\u0646\u0679 \u0644\u06cc\u0628\u0644"},
